const prices = { A: 10, B: 25, CHEAP: 0.1, CENTS: 19.99, EXACT: 100, PENNY: 100.01 }
const msw = setupServer(
  http.get(`${pricingUrl}/prices/:sku`, ({ params }) => HttpResponse.json({ price: prices[params.sku] })),
)
let server, base

