  msw.listen({ onUnhandledRequest: 'error' })
  server = createServer(createApp({ pricing: createPricingClient(pricingUrl) }))
  await new Promise((r) => server.listen(0, '127.0.0.1', r))
  base = `http://127.0.0.1:${server.address().port}`
})
