  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const order = await res.json()
  assert.deepEqual({ ...order, id: typeof order.id }, { id: 'string', items: [{ sku: 'A', qty: 2 }], total: 20 })
})

