  assert.equal(await totalFor([{ sku: 'EXACT', qty: 1 }]), 100)
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount above 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 20 }]), 180)
  assert.equal(await totalFor([{ sku: 'B', qty: 40 }]), 900)
})

