  // CHARACTERIZATION: current behaviour may be unintended — 19.99 is stored as 19; total is whole euros.
  assert.equal(await totalFor([{ sku: 'CENTS', qty: 1 }]), 19)
  assert.equal(await totalFor([{ sku: 'CENTS', qty: 5 }]), 99)
})

test('floating point sums are floored after summation', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 0.1 * 30 = 3.0000000000000004 floors to 3.
  assert.equal(await totalFor([{ sku: 'CHEAP', qty: 30 }]), 3)
})

